import { useEffect, useMemo, useState } from "react";
import { Card, Stack, Text, VegaChart, callFunction, setData, theme, useData } from "a2ui";

type Row = { year: number; balance: number; label: string };

function schedule(principal: number, ratePct: number, payment: number) {
  const rows: { year: number; balance: number }[] = [];
  let balance = principal;
  for (let year = 1; year <= 10; year++) {
    balance = Math.max(0, balance * (1 + ratePct / 100) - payment);
    rows.push({ year, balance: Math.round(balance) });
  }
  return rows;
}

export default function App() {
  const [principal] = useData<number>("/loan/principal", 250000);
  const [rate] = useData<number>("/loan/rate", 5);
  const [payment] = useData<number>("/loan/annualPayment", 30000);
  const [selectedYear, setSelectedYear] = useData<number>("/loan/selectedYear", 0);
  const balances = useMemo(() => schedule(principal, rate, payment), [principal, rate, payment]);
  const [rows, setRows] = useState<Row[]>([]);

  // Format every balance with the catalog's formatCurrency, for tooltips and the summary.
  useEffect(() => {
    let current = true;
    Promise.all(
      balances.map((b) => callFunction<string>("formatCurrency", { value: b.balance, currency: "USD" })),
    ).then((labels) => {
      if (current) setRows(balances.map((b, i) => ({ ...b, label: labels[i] })));
    });
    return () => {
      current = false;
    };
  }, [balances]);

  useEffect(() => {
    const row = rows.find((r) => r.year === selectedYear);
    if (row) setData("/loan/selectedYearSummary", `After year ${row.year}: ${row.label} left to pay`);
  }, [rows, selectedYear]);

  const spec = {
    data: { name: "table" },
    mark: { type: "bar", cursor: "pointer" },
    encoding: {
      x: { field: "year", type: "ordinal", title: "Year" },
      y: { field: "balance", type: "quantitative", title: "Remaining balance" },
      tooltip: [{ field: "label", title: "Balance" }],
      color: {
        condition: { test: `datum.year === ${selectedYear}`, value: theme.colors.primary },
        value: theme.colors.secondary,
      },
    },
  };

  return (
    <Card title="Balance by year">
      <Stack gap={2}>
        <VegaChart
          spec={spec}
          data={{ table: rows }}
          height={240}
          onSelect={(datum) => datum && setSelectedYear(datum.year as number)}
        />
        <Text variant="caption" tone="muted">Click a bar to see that year below.</Text>
      </Stack>
    </Card>
  );
}
